import{_ as a,o as e,c as o,ai as r}from"./chunks/framework.scx6l_IK.js";const q=JSON.parse('{"title":"般若","description":"","frontmatter":{},"headers":[],"relativePath":"50-概念资料/dict-般若.md","filePath":"50-概念资料/dict-般若.md","lastUpdated":1778155802000}'),l={name:"50-概念资料/dict-般若.md"};function d(i,t,h,c,n,u){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="般若" tabindex="-1">般若 <a class="header-anchor" href="#般若" aria-label="Permalink to &quot;般若&quot;">​</a></h1><blockquote><p>传统：佛家 | 道家对应：明道 | 儒家对应：智</p></blockquote><h2 id="了空居士的定义" tabindex="-1">了空居士的定义 <a class="header-anchor" href="#了空居士的定义" aria-label="Permalink to &quot;了空居士的定义&quot;">​</a></h2><p>&quot;般若&quot;就是<strong>看透事物本质的智慧</strong>。不是知识，不是聪明，而是——知道一切现象都不永恒（缘起性空），因而不被它绑住的那种<strong>透彻</strong>。</p><p>了空居士说：有了般若智慧，你就不会把暂时的当真，不会为一时的得失疯狂。般若不是想出来的，是放下执着之后自然呈现的。日常表现就是&quot;心无挂碍&quot;——因为看透了，所以不挂碍。</p><h2 id="原话出处" tabindex="-1">原话出处 <a class="header-anchor" href="#原话出处" aria-label="Permalink to &quot;原话出处&quot;">​</a></h2><blockquote><p>&quot;菩提萨埵，依般若波罗蜜多故，心无挂碍——因为看透了，所以心里没有挂碍。无挂碍故，无有恐怖。&quot;</p></blockquote><blockquote><p>&quot;远离颠倒梦想，究竟涅槃——颠倒就是把假的当成真的，把暂时的当成永恒的。远离了，就涅槃了。&quot;</p></blockquote><h2 id="常见误解" tabindex="-1">常见误解 <a class="header-anchor" href="#常见误解" aria-label="Permalink to &quot;常见误解&quot;">​</a></h2><table tabindex="0"><thead><tr><th>误解</th><th>正解</th></tr></thead><tbody><tr><td>般若是很高深的哲学</td><td>般若就是&quot;看透了&quot;，是每个人都能体会的</td></tr><tr><td>修行好了才有般若</td><td>一念转过来就是般若——当下看透，当下就有</td></tr></tbody></table><h2 id="相关概念" tabindex="-1">相关概念 <a class="header-anchor" href="#相关概念" aria-label="Permalink to &quot;相关概念&quot;">​</a></h2><ul><li><a href="/50-概念资料/dict-菩提">dict-菩提</a> — 菩提就是般若的觉悟状态</li><li><a href="/50-概念资料/dict-观照">dict-观照</a> — 观照是培养般若的具体方法</li><li><a href="/50-概念资料/dict-无明">dict-无明</a> — 无明是般若的反面</li></ul><h2 id="相关模型" tabindex="-1">相关模型 <a class="header-anchor" href="#相关模型" aria-label="Permalink to &quot;相关模型&quot;">​</a></h2><ul><li><a href="/10-核心模型/model-天人合一">model-天人合一</a> — 般若智慧看到的就是万物一体、缘起性空</li><li><a href="/10-核心模型/model-对境不住">model-对境不住</a> — 般若让你对境不动心</li></ul><h2 id="修行实践" tabindex="-1">修行实践 <a class="header-anchor" href="#修行实践" aria-label="Permalink to &quot;修行实践&quot;">​</a></h2><p>遇到困扰时问自己&quot;这件事十年后还重要吗？&quot;——这就是在启动般若智慧。不把暂时的当真，不被一时的得失绑住。</p>',16)])])}const b=a(l,[["render",d]]);export{q as __pageData,b as default};
